// Generated by Heron Brush: the level's keyframe animation and trigger volumes for
// GDevelop. Re-exporting replaces this event; put your own events in another sheet.
//
// Poses are worked in the level's frame (right-handed, Y up, metres) and written to
// GDevelop's (X right, Y down the screen, Z up, pixels): x = X, y = Z, elevation = Y.
// Game code reaches the level through runtimeScene.__heronLevels[name]: play(entity,
// clip), activate(trigger), the per-entity objects, and water: water(point) and
// swim(...) in the level's frame, waterAt(object) for an object. While the camera is
// in water the scene's fog becomes the water's.
const DATA = __DATA__;
const levels = runtimeScene.__heronLevels || (runtimeScene.__heronLevels = {});
let H = levels[DATA.level];
if (!H) {
  const S = DATA.pixelsPerMetre;
  const mul = (a, b) => [
    a[3]*b[0] + a[0]*b[3] + a[1]*b[2] - a[2]*b[1],
    a[3]*b[1] - a[0]*b[2] + a[1]*b[3] + a[2]*b[0],
    a[3]*b[2] + a[0]*b[1] - a[1]*b[0] + a[2]*b[3],
    a[3]*b[3] - a[0]*b[0] - a[1]*b[1] - a[2]*b[2]];
  const axis = (x, y, z, angle) => { const s = Math.sin(angle/2); return [x*s, y*s, z*s, Math.cos(angle/2)]; };
  const rotate = (q, v) => {
    const r = mul(mul(q, [v[0], v[1], v[2], 0]), [-q[0], -q[1], -q[2], q[3]]);
    return [r[0], r[1], r[2]];
  };
  // The rotation as GDevelop's angle, rotationY and rotationX (Z, then Y, then X
  // applied first) in its own axes, where Y and Z trade places.
  const euler = (q) => {
    const [x, y, z, w] = q;
    const m = [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
               [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
               [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)]];
    const p = [0, 2, 1], g = (i, j) => m[p[i]][p[j]];
    const d = 180/Math.PI, s = Math.max(-1, Math.min(1, g(2, 0)));
    return Math.abs(s) < 0.9999999
      ? {angle: Math.atan2(g(1, 0), g(0, 0))*d, rotationY: -Math.asin(s)*d, rotationX: Math.atan2(g(2, 1), g(2, 2))*d}
      : {angle: Math.atan2(-g(0, 1), g(1, 1))*d, rotationY: -Math.asin(s)*d, rotationX: 0};
  };
  const instances = (name) => runtimeScene.getObjects(name) || [];
  const entities = {};
  for (const e of DATA.entities) {
    entities[e.name] = Object.assign({}, e, {objects: e.objects.flatMap(instances)});
  }
  const place = (e, position, rotation) => {
    const r = euler(rotation);
    for (const o of e.objects) {
      o.setX(position[0]*S); o.setY(position[2]*S); o.setZ(position[1]*S);
      o.setAngle(r.angle); o.setRotationY(r.rotationY); o.setRotationX(r.rotationX);
    }
  };
  const sample = (keys, time) => {
    if (!keys.length) return 0;
    if (time <= keys[0].time) return keys[0].value;
    let i = 0;
    while (i + 1 < keys.length && keys[i + 1].time <= time) i++;
    const a = keys[i], b = keys[i + 1];
    if (!b || a.interpolation === 'hold') return a.value;
    const span = b.time - a.time, f = (time - a.time)/span, u = 1 - f;
    if (a.interpolation === 'bezier') return u*u*u*a.value + 3*u*u*f*(a.value + a.outgoing*span/3) +
      3*u*f*f*(b.value - b.incoming*span/3) + f*f*f*b.value;
    return a.value + (b.value - a.value)*f;
  };
  class Animation {
    constructor(e) {
      this.e = e; this.data = JSON.parse(e.animation);
      this.clip = this.data.clips.find(c => c.name === this.data.selected);
      this.time = 0; this.playing = this.posed = this.data.autoplay;
    }
    play(name) {
      const clip = this.data.clips.find(c => c.name === (name || this.data.selected));
      if (!clip) return false;
      this.clip = clip; this.time = 0; this.playing = this.posed = true; return true;
    }
    activate() {
      if (['open', 'close'].every(n => this.data.clips.some(c => c.name === n))) {
        const phase = Math.min(this.time/this.clip.duration, 1), reverse = this.playing && this.posed;
        this.play(this.clip.name === 'open' && this.posed ? 'close' : 'open');
        if (reverse) this.time = (1 - phase)*this.clip.duration;
      } else this.play(this.data.selected);
    }
    pause() { this.playing = false; }
    resume() { this.playing = this.posed = true; }
    stop() { this.playing = this.posed = false; this.time = 0; }
    update(dt) {
      const c = this.clip, e = this.e;
      if (this.playing) {
        this.time += dt;
        if (c.mode === 'once' && this.time >= c.duration) { this.time = c.duration; this.playing = false; }
        else if (c.mode !== 'once') this.time %= c.duration*(c.mode === 'pingpong' ? 2 : 1);
      }
      if (!this.posed) { place(e, e.position, e.rotation); return; }
      let t = c.mode === 'once' ? Math.min(this.time, c.duration) : this.time % (c.duration*(c.mode === 'pingpong' ? 2 : 1));
      if (t > c.duration) t = 2*c.duration - t;
      const v = c.channels.map(channel => sample(channel.keys, t)), r = Math.PI/180, s = this.data.scale, p = this.data.pivot;
      // Y, then X, then Z applied first: the YXZ order every Heron Brush runtime uses.
      const q = mul(mul(axis(0, 1, 0, v[5]*r), axis(1, 0, 0, v[4]*r)), axis(0, 0, 1, v[3]*r));
      const pivot = [p[1]/s, p[2]/s, p[0]/s];
      const turned = rotate(q, [e.position[0] - pivot[0], e.position[1] - pivot[1], e.position[2] - pivot[2]]);
      place(e, [turned[0] + pivot[0] + v[1]/s, turned[1] + pivot[1] + v[2]/s, turned[2] + pivot[2] + v[0]/s], mul(q, e.rotation));
    }
  }
  const animations = {};
  for (const e of Object.values(entities)) if (e.animation) animations[e.name] = new Animation(e);
  const triggers = Object.values(entities).filter(e => e.trigger).map(e => ({e, data: JSON.parse(e.trigger), inside: new Set(), wait: 0, fired: false, pending: false}));
  // Anything with a true HeronActivator variable walks into trigger volumes.
  const activators = () => runtimeScene.getAdhocListOfAllInstances().filter(o => {
    const v = o.getVariables();
    return v.has('HeronActivator') && v.get('HeronActivator').getAsBoolean();
  });
  const step = (dt) => {
    const walkers = activators();
    for (const t of triggers) {
      t.wait = Math.max(0, t.wait - dt);
      const inside = new Set(), d = t.data, e = t.e, back = [-e.rotation[0], -e.rotation[1], -e.rotation[2], e.rotation[3]];
      for (const o of walkers) {
        const world = [o.getCenterXInScene()/S, o.getZ()/S, o.getCenterYInScene()/S];
        const local = rotate(back, [world[0] - e.position[0], world[1] - e.position[1], world[2] - e.position[2]]).map((x, i) => x/e.scale[i]);
        const at = [local[0] + d.origin[0], local[1] + d.origin[1], local[2] + d.origin[2]];
        if (d.volumes.some(planes => planes.length && planes.every(v => v[0]*at[0] + v[1]*at[1] + v[2]*at[2] <= v[3] + 1e-5))) inside.add(o);
      }
      const entered = [...inside].some(o => !t.inside.has(o));
      t.inside = inside;
      const requested = t.pending || entered; t.pending = false;
      if (!requested || t.wait > 0 || (d.once && t.fired)) continue;
      t.wait = d.wait; t.fired = true;
      for (const name of d.targets || []) {
        const a = animations[name];
        if (!a) continue;
        switch (d.action) {
          case 'play': a.play(d.clip || a.data.selected); break;
          case 'open': case 'close': a.play(d.action); break;
          case 'pause': a.pause(); break;
          case 'resume': a.resume(); break;
          case 'stop': a.stop(); break;
          default: a.activate();
        }
      }
    }
    for (const a of Object.values(animations)) a.update(dt);
    view(dt);
  };
  // Water volumes: entity-local convex planes in metres, as every Heron Brush runtime
  // reads them. Where volumes overlap the higher priority wins, then the deeper.
  const waters = Object.values(entities).filter(e => e.water).map(e => ({e, data: JSON.parse(e.water), uniforms: []}));
  const water = (point) => {
    let best = null;
    for (const w of waters) {
      const e = w.e, back = [-e.rotation[0], -e.rotation[1], -e.rotation[2], e.rotation[3]];
      const p = rotate(back, [point[0] - e.position[0], point[1] - e.position[1], point[2] - e.position[2]]).map((x, i) => x/e.scale[i]);
      let depth = -Infinity;
      for (const v of w.data.volumes) {
        if (v.planes.length >= 4 && v.planes.every(q => q.x*p[0] + q.y*p[1] + q.z*p[2] <= q.d + 1e-5)) depth = Math.max(depth, (v.surface - p[1])*Math.abs(e.scale[1]));
      }
      if (depth < 0) continue;
      if (!best || w.data.priority > best.data.priority || (w.data.priority === best.data.priority && depth > best.depth)) best = {name: e.name, data: w.data, depth};
    }
    return best;
  };
  // An object's place in the level's frame: GDevelop's x, z and y, in metres.
  const waterAt = (o) => water([o.getCenterXInScene()/S, (o.getZ() + (o.getDepth ? o.getDepth()/2 : 0))/S, o.getCenterYInScene()/S]);
  // Swimming velocity in metres per second, level frame: walk steers in the
  // horizontal plane (capped at length 1), rise and dive move up and down, and with
  // neither the body sinks slowly; the current velocity eases towards that.
  const swim = (data, current, walk, rise, dive, dt) => {
    const length = Math.hypot(walk[0], walk[1], walk[2]), k = length > 1 ? 1/length : 1;
    const wish = [walk[0]*k*data.swim_speed, (rise ? data.rise_speed : 0) - (dive ? data.rise_speed : 0) - (!rise && !dive ? data.sink_speed : 0), walk[2]*k*data.swim_speed];
    const f = 1 - Math.exp(-data.drag*dt);
    return current.map((v, i) => v + (wish[i] - v)*f);
  };
  // The baseline surface rocks with a small wave; collision does not follow it.
  for (const w of waters) {
    if (!w.data.surface_material || typeof THREE === 'undefined') continue;
    for (const o of w.e.objects) {
      const root = o.get3DRendererObject && o.get3DRendererObject();
      if (!root) continue;
      root.traverse(mesh => {
        if (!mesh.isMesh) return;
        const uniforms = {hbTime: {value: 0}, hbHeight: {value: w.data.wave_height}, hbSpeed: {value: w.data.wave_speed}};
        for (const material of [].concat(mesh.material)) {
          material.onBeforeCompile = shader => {
            Object.assign(shader.uniforms, uniforms);
            shader.vertexShader = 'uniform float hbTime; uniform float hbHeight; uniform float hbSpeed;\n' + shader.vertexShader.replace('#include <begin_vertex>',
              '#include <begin_vertex>\ntransformed.y += smoothstep(0.5, 0.9, normal.y)*hbHeight*sin(position.x*1.7 + hbTime*hbSpeed)*cos(position.z*1.3 - hbTime*hbSpeed*0.8);');
          };
          material.customProgramCacheKey = () => 'heron-water-v1';
          material.needsUpdate = true;
        }
        w.uniforms.push(uniforms);
      });
    }
  }
  let clock = 0, underwater = null, savedFog = null, savedBackground = null;
  const view = (dt) => {
    clock += dt;
    for (const w of waters) for (const u of w.uniforms) u.hbTime.value = clock;
    if (!waters.length || typeof THREE === 'undefined') return;
    const layer = runtimeScene.getLayer(''), three = layer.getRenderer().getThreeScene();
    if (!three) return;
    const at = water([gdjs.evtTools.camera.getCameraX(runtimeScene, '', 0)/S, gdjs.scene3d.camera.getCameraZ(runtimeScene, '', 0)/S,
      gdjs.evtTools.camera.getCameraY(runtimeScene, '', 0)/S]);
    if (at) {
      if (!underwater) { savedFog = three.fog; savedBackground = three.background; underwater = new THREE.FogExp2(0xffffff); }
      const c = at.data.color;
      underwater.color.setRGB(c[0], c[1], c[2]);
      // Fog does not reach the sky, which would show through clear water.
      three.background = underwater.color;
      // Per pixel, scaled to three.js's units as GDevelop's own fog is.
      underwater.density = at.data.fog_density/S*runtimeScene.getScene().getRenderer3DWorldScale();
      three.fog = underwater;
    } else if (underwater) {
      three.fog = savedFog; three.background = savedBackground; underwater = null;
    }
  };
  for (const name of DATA.hidden) for (const o of instances(name)) o.hide(true);
  if (DATA.camera) {
    const c = DATA.camera;
    gdjs.evtTools.camera.setCameraX(runtimeScene, c.x, '', 0);
    gdjs.evtTools.camera.setCameraY(runtimeScene, c.y, '', 0);
    gdjs.scene3d.camera.setCameraZ(runtimeScene, c.z, '', 0);
    gdjs.scene3d.camera.setCameraRotationX(runtimeScene, c.rotationX, '', 0);
    gdjs.evtTools.camera.setCameraRotation(runtimeScene, c.angle, '', 0);
  }
  H = levels[DATA.level] = {
    entities, animations, step,
    play: (name, clip) => animations[name] ? animations[name].play(clip) : false,
    activate: (name) => { const t = triggers.find(t => t.e.name === name); if (t) t.pending = true; },
    water, waterAt, swim,
  };
}
H.step(runtimeScene.getTimeManager().getElapsedTime()/1000);
